class Base(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.path = os.path.join(self.tmp.name, "house.txt")

    def write(self, text, path=None):
        with open(path or self.path, "w", encoding="utf-8", newline="") as f:
            f.write(text)

    def run_cli(self, *argv, stdin=None):
        out, err = io.StringIO(), io.StringIO()
        old_in = sys.stdin
        if stdin is not None:
            sys.stdin = io.TextIOWrapper(io.BytesIO(stdin.encode("utf-8")), encoding="utf-8")
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                code = cli.main(list(argv))
        finally:
            sys.stdin = old_in
        return code, out.getvalue(), err.getvalue()


class ReadCommandTests(Base):
    def setUp(self):
        super().setUp()
        self.write(EXAMPLE)

    def test_balance(self):
        self.assertEqual(self.run_cli("balance", self.path), (0, "1557.50\n", ""))

        self.write("")
        self.assertEqual(self.run_cli("export", self.path)[1], "date,category,amount,note\n")

    def test_stdin(self):
        for argv, want in [
            (("balance", "-"), "1557.50\n"),
            (("summary", "-", "--by", "month"), "2024-03  1557.50\n"),
            (("list", "-", "--category", "rent"), "2024-03-05 rent -900.00\n"),
            (("export", "-"), None),
        ]:
            code, out, err = self.run_cli(*argv, stdin=EXAMPLE)
            self.assertEqual((code, err), (0, ""), argv)
            if want is not None:
                self.assertEqual(out, want)
            else:
                self.assertTrue(out.startswith("date,category,amount,note\n2024-03-01,"))

    def test_stdin_parse_error(self):
        code, out, err = self.run_cli("balance", "-", stdin="\nbad\n")
        self.assertEqual((code, out), (1, ""))
        self.assertIn("line 2", err)


